-- AI RES PostgreSQL physical model v1.0
-- Design migration slice. Requires PostgreSQL 16+ and existing work.tasks,
-- organization/projects, context package versions and worker definition versions.
-- UUIDs are generated by the application (UUIDv7 preferred); no pgcrypto UUID generator assumed.

CREATE SCHEMA IF NOT EXISTS operations;
CREATE SCHEMA IF NOT EXISTS agents;
CREATE SCHEMA IF NOT EXISTS execution;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE SCHEMA IF NOT EXISTS platform;

-- 1. Operation aggregate
CREATE TABLE IF NOT EXISTS operations.operations (
    id UUID PRIMARY KEY,
    organization_id UUID NOT NULL,
    project_id UUID NOT NULL,
    parent_operation_id UUID NULL REFERENCES operations.operations(id) ON DELETE RESTRICT,
    operation_type TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN (
      'ACCEPTED','QUEUED','RUNNING','WAITING_FOR_HUMAN',
      'WAITING_FOR_DEPENDENCY','RETRYING','CANCEL_REQUESTED',
      'SUCCEEDED','PARTIALLY_SUCCEEDED','FAILED','CANCELLED'
    )),
    initiator_type TEXT NOT NULL CHECK (initiator_type IN ('USER','SYSTEM','MANAGER','SERVICE')),
    initiator_id UUID NULL,
    idempotency_scope TEXT NOT NULL,
    request_fingerprint BYTEA NOT NULL CHECK (octet_length(request_fingerprint)=32),
    completion_policy_version TEXT NOT NULL,
    completion_policy_snapshot JSONB NOT NULL,
    correlation_id UUID NOT NULL,
    causation_id UUID NULL,
    workflow_id TEXT NULL,
    workflow_run_id TEXT NULL,
    progress_version BIGINT NOT NULL DEFAULT 0 CHECK (progress_version >= 0),
    progress_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
    result_ref JSONB NULL,
    problem_ref JSONB NULL,
    cancel_requested_at TIMESTAMPTZ NULL,
    started_at TIMESTAMPTZ NULL,
    completed_at TIMESTAMPTZ NULL,
    row_version BIGINT NOT NULL DEFAULT 1 CHECK (row_version > 0),
    last_event_sequence BIGINT NOT NULL DEFAULT 0 CHECK (last_event_sequence >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by UUID NULL,
    updated_by UUID NULL,
    CHECK (parent_operation_id IS NULL OR parent_operation_id <> id),
    CHECK ((status IN ('SUCCEEDED','PARTIALLY_SUCCEEDED','FAILED','CANCELLED')) = (completed_at IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS ix_operations_project_created
  ON operations.operations(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_operations_parent
  ON operations.operations(parent_operation_id) WHERE parent_operation_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_operations_active_status
  ON operations.operations(status, updated_at)
  WHERE status NOT IN ('SUCCEEDED','PARTIALLY_SUCCEEDED','FAILED','CANCELLED');

-- 2. Associate existing Tasks with exactly one Operation (expand/backfill/contract).
ALTER TABLE work.tasks ADD COLUMN IF NOT EXISTS operation_id UUID NULL;
-- MIGRATION GATE: execute this phase only after an approved legacy mapping has
-- backfilled every existing Task to exactly one Operation and orphan checks pass.
-- In a versioned migration after backfill:
-- ALTER TABLE work.tasks ALTER COLUMN operation_id SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_tasks_operation_id_id
  ON work.tasks(operation_id, id);
-- Then add the FK in a guarded migration (NOT inline in a re-runnable design script):
-- ALTER TABLE work.tasks ADD CONSTRAINT fk_tasks_operation
--   FOREIGN KEY (operation_id) REFERENCES operations.operations(id) ON DELETE RESTRICT;

-- 3. Operation event history
CREATE TABLE IF NOT EXISTS operations.operation_events (
    event_id UUID PRIMARY KEY,
    operation_id UUID NOT NULL REFERENCES operations.operations(id) ON DELETE RESTRICT,
    aggregate_sequence BIGINT NOT NULL CHECK (aggregate_sequence > 0),
    aggregate_version BIGINT NOT NULL CHECK (aggregate_version > 0),
    event_type TEXT NOT NULL,
    schema_version INTEGER NOT NULL CHECK (schema_version > 0),
    source TEXT NOT NULL,
    subject TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    correlation_id UUID NOT NULL,
    causation_id UUID NULL,
    actor_type TEXT NOT NULL,
    actor_id UUID NULL,
    reason_code TEXT NULL,
    from_status TEXT NULL,
    to_status TEXT NULL,
    data JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(operation_id, aggregate_sequence)
);
CREATE INDEX IF NOT EXISTS ix_operation_events_time
  ON operations.operation_events(operation_id, occurred_at DESC);

-- 4. WorkerRun aggregate; assumes work.tasks(operation_id,id) unique index/FK has been installed.
CREATE TABLE IF NOT EXISTS agents.worker_runs (
    id UUID PRIMARY KEY,
    organization_id UUID NOT NULL,
    project_id UUID NOT NULL,
    operation_id UUID NOT NULL,
    task_id UUID NOT NULL,
    worker_definition_version_id UUID NOT NULL,
    status TEXT NOT NULL CHECK (status IN (
      'CREATED','PREPARING','WAITING_FOR_GATE','BLOCKED','QUEUED','STARTING',
      'RUNNING','WAITING_FOR_HUMAN','WAITING_FOR_DEPENDENCY','RESULT_SUBMITTED',
      'VALIDATING','REVIEW_PENDING','QA_PENDING','COMPLETED','REWORK_REQUIRED',
      'REJECTED','UNVERIFIED','FAILED','TIMED_OUT','CANCELLED'
    )),
    derived_from_worker_run_id UUID NULL REFERENCES agents.worker_runs(id) ON DELETE RESTRICT,
    derivation_reason TEXT NULL CHECK (derivation_reason IS NULL OR derivation_reason IN
      ('RETRY','REWORK','NEW_CONTEXT','INDEPENDENT_REVIEW','REEXECUTION')),
    attempt_number INTEGER NOT NULL DEFAULT 1 CHECK (attempt_number > 0),
    context_package_version_id UUID NOT NULL,
    latest_readiness_evaluation_id UUID NULL,
    started_with_readiness_evaluation_id UUID NULL,
    workflow_id TEXT NULL,
    workflow_run_id TEXT NULL,
    input_contract_version TEXT NOT NULL,
    output_contract_version TEXT NOT NULL,
    execution_envelope_ref JSONB NULL,
    result_ref JSONB NULL,
    problem_ref JSONB NULL,
    started_at TIMESTAMPTZ NULL,
    finished_at TIMESTAMPTZ NULL,
    deadline_at TIMESTAMPTZ NULL,
    row_version BIGINT NOT NULL DEFAULT 1 CHECK (row_version > 0),
    last_event_sequence BIGINT NOT NULL DEFAULT 0 CHECK (last_event_sequence >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by UUID NULL,
    updated_by UUID NULL,
    CHECK (derived_from_worker_run_id IS NULL OR derived_from_worker_run_id <> id),
    CHECK ((status IN ('COMPLETED','REWORK_REQUIRED','REJECTED','UNVERIFIED','FAILED','TIMED_OUT','CANCELLED')) = (finished_at IS NOT NULL)),
    FOREIGN KEY (operation_id, task_id)
      REFERENCES work.tasks(operation_id, id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS ix_worker_runs_operation_created
  ON agents.worker_runs(operation_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_worker_runs_task_created
  ON agents.worker_runs(task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_worker_runs_lineage
  ON agents.worker_runs(derived_from_worker_run_id) WHERE derived_from_worker_run_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_worker_runs_schedulable
  ON agents.worker_runs(status, created_at)
  WHERE status IN ('CREATED','PREPARING','WAITING_FOR_GATE','QUEUED','STARTING');

-- 5. Readiness evaluations and check results; immutable after completion by domain permissions.
CREATE TABLE IF NOT EXISTS execution.readiness_evaluations (
    id UUID PRIMARY KEY,
    worker_run_id UUID NOT NULL REFERENCES agents.worker_runs(id) ON DELETE RESTRICT,
    evaluation_number INTEGER NOT NULL CHECK (evaluation_number > 0),
    evaluation_status TEXT NOT NULL CHECK (evaluation_status IN ('IN_PROGRESS','COMPLETED','EVALUATOR_ERROR')),
    gate_outcome TEXT NULL CHECK (gate_outcome IS NULL OR gate_outcome IN ('READY','READY_WITH_LIMITATIONS','BLOCKED','STALE')),
    snapshot_hash BYTEA NOT NULL CHECK (octet_length(snapshot_hash)=32),
    task_version BIGINT NOT NULL,
    plan_version_id UUID NULL,
    worker_definition_version_id UUID NOT NULL,
    context_package_version_id UUID NOT NULL,
    ruleset_version TEXT NOT NULL,
    policy_engine_version TEXT NOT NULL,
    grant_snapshot_ref JSONB NOT NULL,
    tool_allowlist_snapshot JSONB NOT NULL,
    output_contract_version TEXT NOT NULL,
    budget_profile_version TEXT NOT NULL,
    dependency_snapshot JSONB NOT NULL,
    evaluator_version TEXT NOT NULL,
    blockers JSONB NOT NULL DEFAULT '[]'::jsonb,
    limitations JSONB NOT NULL DEFAULT '[]'::jsonb,
    evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
    evaluated_at TIMESTAMPTZ NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(worker_run_id, evaluation_number),
    UNIQUE(worker_run_id, id)
);
CREATE TABLE IF NOT EXISTS execution.readiness_check_results (
    id UUID PRIMARY KEY,
    worker_run_id UUID NOT NULL,
    readiness_evaluation_id UUID NOT NULL,
    check_code TEXT NOT NULL,
    result TEXT NOT NULL CHECK (result IN ('PASS','FAIL','WARN','NOT_APPLICABLE')),
    severity TEXT NOT NULL CHECK (severity IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL')),
    reason_code TEXT NULL,
    evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (worker_run_id, readiness_evaluation_id)
      REFERENCES execution.readiness_evaluations(worker_run_id, id) ON DELETE RESTRICT,
    UNIQUE(readiness_evaluation_id, check_code)
);
CREATE INDEX IF NOT EXISTS ix_readiness_eval_worker_created
  ON execution.readiness_evaluations(worker_run_id, created_at DESC);

-- Add composite FK from WorkerRun to its evaluations after both tables exist.
ALTER TABLE agents.worker_runs
  ADD CONSTRAINT fk_worker_run_latest_readiness
  FOREIGN KEY (id, latest_readiness_evaluation_id)
  REFERENCES execution.readiness_evaluations(worker_run_id, id)
  DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE agents.worker_runs
  ADD CONSTRAINT fk_worker_run_started_readiness
  FOREIGN KEY (id, started_with_readiness_evaluation_id)
  REFERENCES execution.readiness_evaluations(worker_run_id, id)
  DEFERRABLE INITIALLY DEFERRED;

-- 6. WorkerRun event history
CREATE TABLE IF NOT EXISTS agents.worker_run_events (
    event_id UUID PRIMARY KEY,
    worker_run_id UUID NOT NULL REFERENCES agents.worker_runs(id) ON DELETE RESTRICT,
    aggregate_sequence BIGINT NOT NULL CHECK (aggregate_sequence > 0),
    aggregate_version BIGINT NOT NULL CHECK (aggregate_version > 0),
    event_type TEXT NOT NULL,
    schema_version INTEGER NOT NULL CHECK (schema_version > 0),
    source TEXT NOT NULL,
    subject TEXT NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL,
    correlation_id UUID NOT NULL,
    causation_id UUID NULL,
    actor_type TEXT NOT NULL,
    actor_id UUID NULL,
    reason_code TEXT NULL,
    from_status TEXT NULL,
    to_status TEXT NULL,
    data JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(worker_run_id, aggregate_sequence)
);
CREATE INDEX IF NOT EXISTS ix_worker_run_events_time
  ON agents.worker_run_events(worker_run_id, occurred_at DESC);

-- 7. Idempotency records. key_digest is HMAC-SHA256; raw client key is never stored.
CREATE TABLE IF NOT EXISTS platform.idempotency_records (
    id UUID PRIMARY KEY,
    scope_type TEXT NOT NULL,
    scope_id UUID NOT NULL,
    key_digest BYTEA NOT NULL CHECK (octet_length(key_digest)=32),
    request_fingerprint BYTEA NOT NULL CHECK (octet_length(request_fingerprint)=32),
    resource_type TEXT NULL,
    resource_id UUID NULL,
    status TEXT NOT NULL CHECK (status IN ('IN_PROGRESS','COMPLETED','REJECTED')),
    response_status INTEGER NULL,
    response_body_ref JSONB NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ NULL,
    UNIQUE(scope_type, scope_id, key_digest)
);
CREATE INDEX IF NOT EXISTS ix_idempotency_expiry
  ON platform.idempotency_records(expires_at);

-- 8. Outbox: one row per event per destination.
CREATE TABLE IF NOT EXISTS audit.outbox_events (
    id UUID PRIMARY KEY,
    event_id UUID NOT NULL,
    destination TEXT NOT NULL,
    aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('OPERATION','WORKER_RUN')),
    aggregate_id UUID NOT NULL,
    aggregate_sequence BIGINT NOT NULL CHECK (aggregate_sequence > 0),
    event_type TEXT NOT NULL,
    schema_version INTEGER NOT NULL CHECK (schema_version > 0),
    envelope JSONB NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('PENDING','IN_FLIGHT','PUBLISHED','QUARANTINED')),
    available_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
    last_error_code TEXT NULL,
    lease_owner TEXT NULL,
    lease_until TIMESTAMPTZ NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at TIMESTAMPTZ NULL,
    UNIQUE(event_id, destination),
    UNIQUE(aggregate_type, aggregate_id, aggregate_sequence, destination)
);
CREATE INDEX IF NOT EXISTS ix_outbox_pending
  ON audit.outbox_events(available_at, created_at)
  WHERE status IN ('PENDING','IN_FLIGHT');
CREATE INDEX IF NOT EXISTS ix_outbox_aggregate_order
  ON audit.outbox_events(aggregate_type, aggregate_id, aggregate_sequence, destination);

-- 9. Inbox deduplication and processing checkpoint.
CREATE TABLE IF NOT EXISTS audit.inbox_messages (
    id UUID PRIMARY KEY,
    consumer_name TEXT NOT NULL,
    event_id UUID NOT NULL,
    aggregate_type TEXT NOT NULL,
    aggregate_id UUID NOT NULL,
    aggregate_sequence BIGINT NOT NULL CHECK (aggregate_sequence > 0),
    status TEXT NOT NULL CHECK (status IN ('PROCESSING','PROCESSED','QUARANTINED')),
    payload_hash BYTEA NOT NULL CHECK (octet_length(payload_hash)=32),
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    processed_at TIMESTAMPTZ NULL,
    error_code TEXT NULL,
    UNIQUE(consumer_name, event_id)
);
CREATE INDEX IF NOT EXISTS ix_inbox_consumer_status
  ON audit.inbox_messages(consumer_name, status, received_at);

-- 10. Notes:
-- * Add immutable-event triggers / revoke UPDATE, DELETE from runtime roles.
-- * Add Task operation_id NOT NULL + composite unique/FK only after approved backfill.
-- * Validate status transitions in domain services; CHECK constraints validate vocabulary only.
